#include <iostream>

class Rect {
public:
    Rect(int width, int height) : width_(width), height_(height) {}
    int area() const { return width_ * height_; }
    int perimeter() const { return 2 * (width_ + height_); }
private:
    int width_ = 0;
    int height_ = 0;
};

int main() {
    int w = 0;
    int h = 0;
    std::cin >> w >> h;
    Rect rect(w, h);
    std::cout << rect.area() << std::endl;
    std::cout << rect.perimeter() << std::endl;
    return 0;
}
